/**
 * Dev-only vendoring pipeline for the syntax-highlighting feature (spec §7.1)
 * and the CM6 content-surface migration.
 *
 * Pre-bundles Shiki v3 — core + JavaScript regex engine (no WASM) + the
 * css-variables theme + the three warmup grammars — plus the four language
 * groups from @shikijs/langs into self-contained, minified ESM files under
 * src/vendor/ that are COMMITTED to the repo. build.mjs and the publish flow
 * never touch node_modules; upgrading Shiki means re-running this script and
 * committing the regenerated files.
 *
 * Also pre-bundles the CodeMirror 6 core — @codemirror/state, view, commands
 * and language, deliberately NOT @codemirror/search (spec §12-6: cut on
 * bundle size, highlightSelectionMatches is unused this milestone) — into
 * src/vendor/cm6-core.js, a committed self-contained module exporting the
 * single `cm6` whitelist record. Same discipline applies: transitive
 * dependencies (@lezer/*, style-mod, w3c-keyname, crelt) arrive via
 * bundling, not direct installs; upgrading CM6 means re-running this script
 * and committing the regenerated file.
 *
 * The outputs are generated artifacts — never hand-edit them; regenerate via:
 *
 *     node scripts/vendor.mjs
 *
 * The facades are the contract later tasks import (`createCoreFacade()` from
 * src/vendor/shiki-core.js, the `cm6` record from src/vendor/cm6-core.js);
 * the Shiki specifiers below are an implementation
 * detail of this script, verified against the installed shiki 3.23.0:
 *   - `shiki/core`            → createHighlighterCore, createCssVariablesTheme
 *   - `shiki/engine/javascript` → createJavaScriptRegexEngine
 *   - `@shikijs/langs/<lang>` → default-exported TextMate grammar object
 */

import { build } from 'esbuild';
import { mkdirSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = path.join(ROOT, 'src', 'vendor');

/** Warmup grammars bundled into the facade itself (open-with-zero-wait set). */
const WARMUP_LANGUAGES = ['javascript', 'typescript', 'json'];

/** Spec §4 lazy-load groups; each becomes one committed lang-<group>.js file. */
const LANGUAGE_GROUPS = {
	web: ['html', 'css', 'scss', 'less', 'vue', 'svelte'],
	script: ['shellscript', 'python', 'ruby', 'php', 'perl', 'lua', 'powershell'],
	system: ['c', 'cpp', 'csharp', 'go', 'java', 'kotlin', 'rust', 'swift'],
	data: ['yaml', 'toml', 'ini', 'xml', 'sql', 'markdown', 'diff', 'dotenv'],
};

const BANNER = '/* Generated by scripts/vendor.mjs - do not edit; re-run the script instead. */';

/**
 * Entry template for src/vendor/shiki-core.js. Implements the facade over raw
 * Shiki: the only module in the feature allowed to touch the engine. All
 * Shiki API-surface risk (exact method names, GrammarState equality) is
 * contained here.
 *
 * - ensureReady() creates the singleton highlighter (JS regex engine +
 *   css-variables theme + warmup grammars) lazily; createCoreFacade() itself
 *   starts no work.
 * - loadLanguageSync() maps to highlighter.loadLanguageSync (shiki 3.x).
 * - tokenizeLine() maps to codeToTokensBase + getLastGrammarState over the
 *   token result (WeakMap lookup, no re-tokenization); maxLineLength maps to
 *   Shiki's tokenizeMaxLineLength ("lines above this length are not
 *   tokenized").
 * - statesEqual() uses GrammarState equality: shiki's GrammarState class has
 *   no equals, but its getInternalStack() exposes the vscode-textmate
 *   StateStack whose public equals() compares rule ids, end rules and scope
 *   stacks — the exact convergence semantics the incremental tokenizer
 *   needs. Falls back to identity when stacks are unavailable.
 */
const CORE_ENTRY = `import { createHighlighterCore, createCssVariablesTheme } from 'shiki/core';
import { createJavaScriptRegexEngine } from 'shiki/engine/javascript';
${WARMUP_LANGUAGES.map((lang) => `import ${lang} from '@shikijs/langs/${lang}';`).join('\n')}

const THEME_NAME = 'css-variables';
const WARMUP_GRAMMARS = [${WARMUP_LANGUAGES.join(', ')}];

export function createCoreFacade() {
	let highlighter = null;
	let readyPromise = null;

	function ensureReady() {
		if (highlighter !== null) return Promise.resolve();
		if (readyPromise === null) {
			readyPromise = createHighlighterCore({
				themes: [createCssVariablesTheme({ name: THEME_NAME })],
				langs: WARMUP_GRAMMARS,
				engine: createJavaScriptRegexEngine(),
			}).then((created) => {
				highlighter = created;
			});
		}
		return readyPromise;
	}

	function assertReady(method) {
		if (highlighter === null) {
			throw new Error('shiki core not ready: await ensureReady() before calling ' + method + '()');
		}
	}

	function isLanguageLoaded(lang) {
		return highlighter !== null && highlighter.getLoadedLanguages().includes(lang);
	}

	function loadLanguageSync(grammar) {
		assertReady('loadLanguageSync');
		highlighter.loadLanguageSync(grammar);
	}

	function tokenizeLine(line, opts) {
		assertReady('tokenizeLine');
		const options = {
			lang: opts.lang,
			theme: THEME_NAME,
			tokenizeMaxLineLength: opts.maxLineLength,
		};
		if (opts.grammarState !== undefined) options.grammarState = opts.grammarState;
		const lines = highlighter.codeToTokensBase(line, options);
		const tokens = (lines[0] ?? []).map((token) => ({
			content: token.content,
			start: token.offset,
			end: token.offset + token.content.length,
			color: token.color ?? '',
			fontStyle: token.fontStyle ?? 0,
		}));
		return { tokens, grammarState: highlighter.getLastGrammarState(lines) };
	}

	function statesEqual(a, b) {
		if (a === b) return true;
		if (a == null || b == null) return false;
		if (typeof a.getInternalStack !== 'function' || typeof b.getInternalStack !== 'function') return false;
		const stackA = a.getInternalStack();
		const stackB = b.getInternalStack();
		if (stackA == null || stackB == null || typeof stackA.equals !== 'function') return false;
		return a.lang === b.lang && stackA.equals(stackB);
	}

	return { ensureReady, isLanguageLoaded, loadLanguageSync, tokenizeLine, statesEqual };
}
`;

function groupEntry(languages) {
	const imports = languages.map((lang) => `import ${lang} from '@shikijs/langs/${lang}';`).join('\n');
	const members = languages.join(', ');
	return `${imports}\n\nexport const languages = { ${members} };\n`;
}

/**
 * Entry template for src/vendor/cm6-core.js. The `cm6` record is the flat
 * whitelist of CodeMirror 6 value symbols the content-surface feature is
 * allowed to use — the only module in the feature that may import CM6.
 * Task 3's chunk section and Task 8's view.js (via the loader) consume it;
 * the specifiers below are an implementation detail of this script, verified
 * against the installed @codemirror/state 6.7.6, view 6.44.2, commands
 * 6.11.2, language 6.13.1.
 *
 * The whitelist must stay exactly the set of value imports above — the
 * assertVendored() gate pins the output to the single `cm6` export:
 *   - EditorRange is deliberately absent: it is a type-only export of
 *     @codemirror/state, so a plain value import would fail the esbuild
 *     bundle ("No matching export"). Consumers treat ranges structurally.
 *   - @codemirror/search symbols are deliberately absent (spec §12-6).
 *   - Node's import smoke needs no stub: @codemirror/view guards its
 *     navigator/document access with typeof checks at module scope.
 */
const CM6_ENTRY = `import { EditorView } from '@codemirror/view';
import { EditorState, Compartment, StateField, StateEffect, Range, RangeSet, RangeSetBuilder, EditorSelection, Text, Annotation, Transaction } from '@codemirror/state';
import { keymap, drawSelection, dropCursor, highlightActiveLine, highlightActiveLineGutter, lineNumbers, rectangularSelection, crosshairCursor, ViewPlugin, Decoration, WidgetType, layer } from '@codemirror/view';
import { indentUnit, indentOnInput, bracketMatching, foldGutter, syntaxHighlighting } from '@codemirror/language';
import { defaultKeymap, history, historyKeymap, indentWithTab, indentMore, indentLess } from '@codemirror/commands';

export const cm6 = { EditorView, EditorState, Compartment, StateField, StateEffect, Range, RangeSet, RangeSetBuilder, EditorSelection, Text, Annotation, Transaction, keymap, drawSelection, dropCursor, highlightActiveLine, highlightActiveLineGutter, lineNumbers, rectangularSelection, crosshairCursor, ViewPlugin, Decoration, WidgetType, layer, indentUnit, indentOnInput, bracketMatching, foldGutter, syntaxHighlighting, defaultKeymap, history, historyKeymap, indentWithTab, indentMore, indentLess };
`;

/**
 * Verifies a generated file is a self-contained ESM module exposing exactly
 * one export. Text-level import/export regexes are useless here: the bundled
 * grammar data legitimately contains regex source strings that mention
 * import/export syntax, so instead:
 *   1. esbuild's metafile is authoritative that the output imports nothing
 *      (no static or dynamic external references survive bundling);
 *   2. importing the file and reading its export surface proves it is valid,
 *      runnable, single-export ESM.
 */
async function assertVendored(result, expectedExport, relPath) {
	const outputs = result.metafile.outputs;
	const imports = outputs[Object.keys(outputs)[0]].imports ?? [];
	if (imports.length > 0) {
		throw new Error(`${relPath}: output still imports ${imports.map((entry) => entry.path).join(', ')} - must be self-contained`);
	}
	const module = await import(pathToFileURL(path.join(ROOT, relPath)).href);
	const names = Object.keys(module);
	if (names.length !== 1 || names[0] !== expectedExport) {
		throw new Error(`${relPath}: expected exactly one export "${expectedExport}", found [${names.join(', ')}]`);
	}
}

async function bundleCore() {
	const relPath = 'src/vendor/shiki-core.js';
	const result = await build({
		stdin: { contents: CORE_ENTRY, resolveDir: ROOT, loader: 'js' },
		bundle: true,
		format: 'esm',
		platform: 'browser',
		minify: true,
		banner: { js: BANNER },
		outfile: path.join(ROOT, relPath),
		metafile: true,
	});
	await assertVendored(result, 'createCoreFacade', relPath);
	return relPath;
}

async function bundleGroup(group, languages) {
	const relPath = `src/vendor/lang-${group}.js`;
	const result = await build({
		stdin: { contents: groupEntry(languages), resolveDir: ROOT, loader: 'js' },
		bundle: true,
		format: 'esm',
		platform: 'browser',
		minify: true,
		banner: { js: BANNER },
		outfile: path.join(ROOT, relPath),
		metafile: true,
	});
	await assertVendored(result, 'languages', relPath);
	return relPath;
}

async function bundleCm6() {
	const relPath = 'src/vendor/cm6-core.js';
	const result = await build({
		stdin: { contents: CM6_ENTRY, resolveDir: ROOT, loader: 'js' },
		bundle: true,
		format: 'esm',
		platform: 'browser',
		minify: true,
		banner: { js: BANNER },
		outfile: path.join(ROOT, relPath),
		metafile: true,
	});
	await assertVendored(result, 'cm6', relPath);
	return relPath;
}

mkdirSync(OUT_DIR, { recursive: true });

const written = [await bundleCore()];
for (const [group, languages] of Object.entries(LANGUAGE_GROUPS)) {
	written.push(await bundleGroup(group, languages));
}
written.push(await bundleCm6());

for (const relPath of written) {
	const bytes = statSync(path.join(ROOT, relPath)).size;
	console.log(`vendored ${relPath} (${(bytes / 1024).toFixed(1)} KiB)`);
}
console.log(`warmup: ${WARMUP_LANGUAGES.join(', ')} | groups: ${Object.entries(LANGUAGE_GROUPS).map(([g, l]) => `${g}(${l.length})`).join(' ')}`);
